$expr=@'
(async()=>{
 history.pushState({},'', '/files/public-b');
 window.dispatchEvent(new PopStateEvent('popstate'));
 await new Promise(r=>setTimeout(r,800));
 const probe=[...document.querySelectorAll('a')].find(e=>(e.textContent||'').trim()==='authz-probe-20260930');
 const row=probe?.closest('tr');
 if(row?.classList.contains('isChecked')){
   const cb=row.querySelector('input[type="checkbox"]');
   if(cb){cb.click(); await new Promise(r=>setTimeout(r,350));}
 }
 const names=[...document.querySelectorAll('button')].filter(e=>{const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&r.width>0&&r.height>0}).map(e=>(e.innerText||e.getAttribute('aria-label')||'').trim()).filter(Boolean);
 return JSON.stringify({path:location.pathname,rowChecked:!!row?.classList.contains('isChecked'),hasNewFolder:names.includes('New Folder'),hasMove:names.includes('Move')});
